const r = await tools.pwsh({
  description: "Search dsh home for grill-first enable state",
  command: `
Get-ChildItem 'C:\\Users\\jjq21\\.dsh' -Recurse -File -ErrorAction SilentlyContinue |
  Where-Object { $_.FullName -notmatch 'node_modules|\\.plugin-manager|profiles\\\\desktop\\\\pnpm-lock' } |
  Select-String -Pattern 'grill-first' -SimpleMatch -List -ErrorAction SilentlyContinue |
  ForEach-Object { $_.Path }
`,
  timeoutMs: 120000,
});
if (r.kind === "foreground") console.log(r.stdout.text.slice(0, 3000), "|ERR|", r.stderr.text.slice(0,500));
